/**
 * Jael's Choice
 * -------------
 * Jael welcomes Sisera with milk and a blanket, and when he sleeps she drives a tent peg through his temple. Stage: the dim interior of a goat-hair tent, a bowl of milk, a figure asleep, the hammer and peg in the firelight; the quietest, darkest stroke of the war.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: tent
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./deborah-kit.js.
 */

import { THREE, createScene, temple, column, tent, sheep, army, cup, person } from './deborah-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 975564743, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* temple: colonnade and glowing doorway */
    const templeG = W.grp(group, [0, 0, -46], { name: 'temple', r: [0, 0.10, 0] });
    temple(W, templeG, 0, 0, 0, 1.1, { stone: 0xac915f, trim: 0x978154 });
    W.backdrop(templeG);

    /* camp: a circle of tents */
    tent(W, group, 16.1, 0, -9.2, 1.21, 0xd8c8a0, W.r() * 6);
    tent(W, group, -23.5, 0, -11.0, 0.98, 0xd8c8a0, W.r() * 6);
    tent(W, group, 26.3, 0, -22.2, 0.98, 0xa8704a, W.r() * 6);

    /* flock: sheep grazing */
    sheep(W, group, -3.7, 0, -6.8, W.r() * 6, 1.17);
    sheep(W, group, -15.7, 0, 4.1, W.r() * 6, 1.20);
    sheep(W, group, -5.7, 0, 1.1, W.r() * 6, 1.09);
    sheep(W, group, -11.4, 0, -7.1, W.r() * 6, 0.83);
    sheep(W, group, -2.4, 0, 0.7, W.r() * 6, 1.01);
    sheep(W, group, 17.8, 0, -1.6, W.r() * 6, 0.96);
    sheep(W, group, -3.5, 0, -6.5, W.r() * 6, 0.98);
    /* army: shields and spears in rank */
    army(W, group, -1.1, 26.7, 11, { shields: [0x8c784e, 0x6b5b3b, 0x8a7a2a, 0x3a5a8a] });

    cup(W, group, -3.7, 0, -6.4, );

    /* hero: the tent */
    tent(W, group, 0, 0, 0, 1.4, 0x9c8456, 0.2);
    W.disc([0, 5, -10], 5, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xd8b878, ry: -0.05, s: 1.07 });
    person(W, group, [4.5, 0, 6], { robe: 0x9c8456, ry: -0.58, s: 1.15 });
    person(W, group, [1, 0, -5], { robe: 0x776542, ry: 0.66, s: 1.03 });

    return W.finish();
}

export default { build };
